import { StyleSheet, } from 'react-native';

const styles = StyleSheet.create({
    container: {
        width: 300,
        height: 300,
        backgroundColor: 'rgba(0,0,0,0.8)',
        borderRadius: 20,
        borderWidth: 3,
        borderColor: '#356',
        position: 'absolute',
        paddingBottom: 50
    },

    containerResultNumber: {
        flexDirection: 'row',
        justifyContent: 'space-around',
        alignItems: 'center'
    },

    textResultNumber: {
        fontSize: 40,
        color: '#fff',
        backgroundColor: '#333',
        borderBottomStartRadius: 20,
        borderBottomEndRadius: 20,
        paddingHorizontal: 20,
    },

    containerNumber: {
        flexDirection: 'row',
        justifyContent: 'space-around',
        alignItems: 'center'
    },

    textNumber: {
        fontSize: 50,
        color: '#fff'
    },

    containerButton: {
        flexDirection: 'row',
        justifyContent: 'space-around',
        alignItems: 'center',
        marginHorizontal: 25
    },

    buttonLimpar: {
        alignItems: 'center',
        justifyContent: 'center'
    },

    textButtonLimpar: {
        fontSize: 20,
        color: '#fff',
        backgroundColor: '#17A2B7',
        paddingHorizontal: 13,
        paddingVertical: 12,
        position: 'absolute',
        borderRadius: 5
    },

    buttonConcluir: {
        alignItems: 'center',
        justifyContent: 'center'
    },

    textButtonConcluir: {
        fontSize: 20,
        color: '#fff',
        backgroundColor: '#26A744',
        position: 'absolute',
        paddingHorizontal: 8,
        paddingVertical: 12,
        borderRadius: 5
    },

});
export { styles };
